#!/bin/bash
# Builds auto-rotate's motion pieces on the build PC (see motion_vdi.cpp, motion_hdi_publisher.cpp):
#   libhdi_motion_impl.z.so: our motion VDI (screen rotation from the accelerometer), over Huawei's in /vendor/lib64.
#   native_motion_hdi_publisher: registers the donor's motion service, with that VDI below it, as
#     motion_interface_service (the asteroids_motion_hdi service).
# The motion HDI 1.0/1.1 C++ headers are generated by hdi-gen from OpenHarmony's drivers_interface/motion, as for
# the sensors (sensors/build-sensors.sh); the VDI interface is drivers_peripheral/motion's.
# Output: $WORK/out-motion/.
set -e
. "$(dirname "$0")/../../../build/env.sh"
HB=${HARMONY_BUILD:-$HOME/harmony-build}
M2=$WORK
N=$HB/ohos/sdk/native
S=$HB/ohos/src
DONOR=$HB/donor/pura70proplus-7.0.0.107/mnt
O=$WORK/out-motion
L=$WORK/out-sensors/link
G=$O/gen
mkdir -p $O
[ -f $L/libhdi.z.so ] || { echo "run sensors/build-sensors.sh first (donor link libraries)"; exit 1; }

HG=$S/drivers_hdf_core/framework/tools/hdi-gen/hdi-gen
I=$O/idl/ohos/hdi/motion
rm -rf $O/idl $G && mkdir -p $I $G
cp -r $S/drivers_interface/motion/v1_0 $S/drivers_interface/motion/v1_1 $I/
for f in v1_0/MotionTypes.idl v1_0/IMotionCallback.idl v1_0/IMotionInterface.idl v1_1/MotionTypes.idl \
         v1_1/IMotionInterface.idl; do
    $HG -s full -m ipc -l cpp -r ohos.hdi:$O/idl/ohos/hdi -c $I/$f -d $G
done

HDF=$S/drivers_hdf_core/interfaces/inner_api
INC="-I$G -I$G/motion -I$HDF/hdi -I$HDF/ipc -I$HDF/hdi/base -I$HDF/utils -I$HDF/osal/uhdf -I$HDF/core -I$HDF/host/uhdf
     -I$S/commonlibrary_c_utils/base/include -I$S/communication_ipc/interfaces/innerkits/ipc_core/include
     -I$S/communication_ipc/interfaces/innerkits/ipc_single/include -I$S/hiviewdfx_hilog/interfaces/native/innerkits/include"
CXX="$N/llvm/bin/clang++ --target=aarch64-linux-ohos --sysroot=$N/sysroot -O2 -Wall -Wextra -std=c++17
     -fno-exceptions -fno-rtti -nostdlib++ -include $COMMON/include/platform_cpp_config.h -fuse-ld=lld"
BASE="$L/libutils.z.so $L/libc++.so $L/libipc_single.z.so $L/libipc_common.z.so -Wl,--allow-shlib-undefined"
$CXX $INC -I$S/drivers_peripheral/motion/interfaces/v1_0 -fPIC -fvisibility=hidden -shared \
    -Wl,-soname,libhdi_motion_impl.z.so $QCOM/motion/motion_vdi.cpp $BASE -lohsensor $WORK/out-zink/link/libhilog.so $L/libbegetutil.z.so -pthread \
    -o $O/libhdi_motion_impl.z.so
$CXX $INC $QCOM/motion/motion_hdi_publisher.cpp $L/libhdi.z.so $L/libhdi_base.z.so $BASE -ldl -pthread \
    -o $O/native_motion_hdi_publisher
ls -l $O/libhdi_motion_impl.z.so $O/native_motion_hdi_publisher
